import 'dart:ui';
import 'package:flutter/material.dart';
class GlassCard extends StatelessWidget {const GlassCard({super.key,required this.child,this.padding=const EdgeInsets.all(16)});final Widget child;final EdgeInsets padding;@override Widget build(BuildContext context){final dark=Theme.of(context).brightness==Brightness.dark;return ClipRRect(borderRadius:BorderRadius.circular(20),child:BackdropFilter(filter:ImageFilter.blur(sigmaX:16,sigmaY:16),child:Container(padding:padding,decoration:BoxDecoration(color:Colors.white.withValues(alpha:dark?.075:.82),borderRadius:BorderRadius.circular(20),border:Border.all(color:dark?Colors.white12:Colors.black12)),child:child)));}}
